INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-01-05', 'lesson-paragraphs-b2-01', 5, 'paragraph', 'My family is not very big, but we are close. My brother lives in the same city, so we meet for dinner every Sunday.', 'Minha família não é muito grande, mas somos próximos. Meu irmão mora na mesma cidade, então nos encontramos para jantar todo domingo.', '/maɪ ˈfæməli ɪz nɑːt ˈvɛri bɪɡ bʌt wiː ɑːr kloʊz maɪ ˈbrʌðər lɪvz ɪn ðə seɪm ˈsɪti soʊ wiː miːt fɔːr ˈdɪnər ˈɛvri ˈsʌndeɪ/', 'Detalhe sobre a família: "but" contrasta e "so" mostra consequência.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"family","pos":"noun","ipa":"/ˈfæməli/","gloss":"família"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"very","pos":"adverb","ipa":"/ˈvɛri/","gloss":"muito"},{"surface":"big","pos":"adjective","ipa":"/bɪɡ/","gloss":"grande"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"close","pos":"verb","ipa":"/kloʊz/","gloss":"fechar"},{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"brother","pos":"noun","ipa":"/ˈbrʌðər/","gloss":"irmão"},{"surface":"lives","pos":"verb","ipa":"/lɪvz/","gloss":"mora, vive"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"same","pos":"adjective","ipa":"/seɪm/","gloss":"mesmo"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"meet","pos":"verb","ipa":"/miːt/","gloss":"encontrar"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"Sunday","pos":"proper noun","ipa":"/ˈsʌndeɪ/","gloss":"domingo"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-01-06', 'lesson-paragraphs-b2-01', 6, 'paragraph', 'Last year, I took a course in emergency care. It was difficult, but it helped me feel more prepared at work.', 'No ano passado, fiz um curso de atendimento de emergência. Foi difícil, mas me ajudou a me sentir mais preparada no trabalho.', '/læst jɪr aɪ tʊk ə kɔːrs ɪn ɪˈmɜːrdʒənsi kɛr ɪt wɑːz ˈdɪfɪkəlt bʌt ɪt hɛlpt miː fiːl mɔːr prɪˈpɛrd æt wɜːrk/', 'Passado simples para um fato concluído. "Feel more prepared" = comparativo com adjetivo longo.', '[]'::jsonb, '[{"surface":"Last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"took","pos":"verb","ipa":"/tʊk/","gloss":"pegou, levou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"course","pos":"noun","ipa":"/kɔːrs/","gloss":"curso (of course = claro)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"emergency","pos":"noun","ipa":"/ɪˈmɜːrdʒənsi/","gloss":"emergência"},{"surface":"care","pos":"noun","ipa":"/kɛr/","gloss":"cuidado"},{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"difficult","pos":"adjective","ipa":"/ˈdɪfɪkəlt/","gloss":"difícil"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"prepared","pos":"adjective","ipa":"/prɪˈpɛrd/","gloss":"disposto, preparado"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-01-07', 'lesson-paragraphs-b2-01', 7, 'paragraph', 'If I could change one thing, I would have more time to travel. I have never been outside Brazil, and that is my biggest dream.', 'Se eu pudesse mudar uma coisa, teria mais tempo para viajar. Nunca saí do Brasil, e esse é meu maior sonho.', '/ɪf aɪ kʊd tʃeɪndʒ wʌn θɪŋ aɪ wʊd hæv mɔːr taɪm tuː ˈtrævəl aɪ hæv ˈnɛvər bɪn ˌaʊtˈsaɪd brəˈzɪl ænd ðæt ɪz maɪ ˈbɪɡɪst driːm/', 'Segunda condicional (if + passado, would) e present perfect com "never".', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"thing","pos":"noun","ipa":"/θɪŋ/","gloss":"coisa"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"travel","pos":"verb","ipa":"/ˈtrævəl/","gloss":"viajar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"},{"surface":"Brazil","pos":"proper noun","ipa":"/brəˈzɪl/","gloss":"Brasil"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"biggest","pos":"adjective","ipa":"/ˈbɪɡɪst/","gloss":"maior"},{"surface":"dream","pos":"verb","ipa":"/driːm/","gloss":"sonhar"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-01-08', 'lesson-paragraphs-b2-01', 8, 'paragraph', 'So, that is a little about me. I hope we can talk more soon, and I would love to hear about you too.', 'Então, isso é um pouco sobre mim. Espero que a gente converse mais em breve, e eu adoraria saber de você também.', '/soʊ ðæt ɪz ə ˈlɪtəl əˈbaʊt miː aɪ hoʊp wiː kæn tɔːk mɔːr suːn ænd aɪ wʊd lʌv tuː hɪr əˈbaʊt juː tuː/', 'Segundo fechamento: devolve a palavra ao leitor com "I would love to".', '[]'::jsonb, '[{"surface":"So","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"little","pos":"adjective","ipa":"/ˈlɪtəl/","gloss":"pouco, pequeno"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"hope","pos":"verb","ipa":"/hoʊp/","gloss":"esperar (ter esperança)"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"talk","pos":"verb","ipa":"/tɔːk/","gloss":"falar"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"soon","pos":"adverb","ipa":"/suːn/","gloss":"logo"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"love","pos":"verb","ipa":"/lʌv/","gloss":"amar, adorar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"hear","pos":"verb","ipa":"/hɪr/","gloss":"ouvir"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-02-05', 'lesson-paragraphs-b2-02', 5, 'paragraph', 'On Saturdays, my routine is completely different. I sleep late, and I do not look at my phone until noon.', 'Aos sábados, minha rotina é completamente diferente. Durmo até tarde e não olho o celular até o meio-dia.', '/ɑːn ˈsætərdeɪz maɪ ruːˈtiːn ɪz kəmˈpliːtli ˈdɪfərənt aɪ sliːp leɪt ænd aɪ duː nɑːt lʊk æt maɪ foʊn ənˈtɪl nuːn/', 'Contraste com o dia de semana. "Until" marca o limite do tempo.', '[]'::jsonb, '[{"surface":"On","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Saturdays","pos":"proper noun","ipa":"/ˈsætərdeɪz/","gloss":"sábados"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"routine","pos":"noun","ipa":"/ruːˈtiːn/","gloss":"rotina"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"completely","pos":"adverb","ipa":"/kəmˈpliːtli/","gloss":"completamente"},{"surface":"different","pos":"adjective","ipa":"/ˈdɪfərənt/","gloss":"diferente"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"sleep","pos":"verb","ipa":"/sliːp/","gloss":"dormir"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"until","pos":"conjunction","ipa":"/ənˈtɪl/","gloss":"até"},{"surface":"noon","pos":"noun","ipa":"/nuːn/","gloss":"meio-dia"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-02-06', 'lesson-paragraphs-b2-02', 6, 'paragraph', 'In the evening, I usually meet friends for dinner. We never plan much, but we always end up laughing.', 'À noite, geralmente encontro amigos para jantar. Nunca planejamos muito, mas sempre acabamos rindo.', '/ɪn ðə ˈiːvnɪŋ aɪ ˈjuːʒuəli miːt frɛndz fɔːr ˈdɪnər wiː ˈnɛvər plæn mʌtʃ bʌt wiː ˈɔːlweɪz ɛnd ʌp ˈlæfɪŋ/', '"End up" + -ing = acabar fazendo algo. Advérbios de frequência antes do verbo.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"evening","pos":"noun","ipa":"/ˈiːvnɪŋ/","gloss":"noite (início), fim de tarde"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"meet","pos":"verb","ipa":"/miːt/","gloss":"encontrar"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"},{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"end","pos":"noun","ipa":"/ɛnd/","gloss":"fim, final"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"laughing","pos":"verb","ipa":"/ˈlæfɪŋ/","gloss":"rindo"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-02-07', 'lesson-paragraphs-b2-02', 7, 'paragraph', 'Of course, some days are harder than others. When work is stressful, I go for a short walk to clear my head.', 'Claro, alguns dias são mais difíceis que outros. Quando o trabalho está estressante, saio para uma caminhada curta para clarear a cabeça.', '/ʌv kɔːrs sʌm deɪz ɑːr ˈhɑːrdər ðæn ˈʌðərz wɛn wɜːrk ɪz ˈstrɛsfəl aɪ ɡoʊ fɔːr ə ʃɔːrt wɔːk tuː klɪr maɪ hɛd/', '"Clear my head" = espairecer. "When" abre uma situação habitual.', '[]'::jsonb, '[{"surface":"Of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"course","pos":"noun","ipa":"/kɔːrs/","gloss":"curso (of course = claro)"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"days","pos":"noun","ipa":"/deɪz/","gloss":"dias"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"harder","pos":"adjective","ipa":"/ˈhɑːrdər/","gloss":"mais difícil"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"others","pos":"pronoun","ipa":"/ˈʌðərz/","gloss":"outros"},{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"stressful","pos":"adjective","ipa":"/ˈstrɛsfəl/","gloss":"estressante"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"short","pos":"adjective","ipa":"/ʃɔːrt/","gloss":"curto"},{"surface":"walk","pos":"noun","ipa":"/wɔːk/","gloss":"caminhada; andar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"clear","pos":"adjective","ipa":"/klɪr/","gloss":"claro"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"head","pos":"noun","ipa":"/hɛd/","gloss":"cabeça"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-02-08', 'lesson-paragraphs-b2-02', 8, 'paragraph', 'All in all, I like having a routine. It helps me use my time well, and it gives me energy for the things I enjoy.', 'No geral, gosto de ter uma rotina. Ela me ajuda a usar bem meu tempo e me dá energia para as coisas de que gosto.', '/ɔːl ɪn ɔːl aɪ laɪk ˈhævɪŋ ə ruːˈtiːn ɪt hɛlps miː juːz maɪ taɪm wɛl ænd ɪt ɡɪvz miː ˈɛnərdʒi fɔːr ðə θɪŋz aɪ ɪnˈdʒɔɪ/', '"All in all" fecha o texto. "Like having" = gostar de ter.', '[]'::jsonb, '[{"surface":"All","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"having","pos":"verb","ipa":"/ˈhævɪŋ/","gloss":"receber, ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"routine","pos":"noun","ipa":"/ruːˈtiːn/","gloss":"rotina"},{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"helps","pos":"verb","ipa":"/hɛlps/","gloss":"ajuda"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"use","pos":"verb","ipa":"/juːz/","gloss":"usar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"well","pos":"adverb","ipa":"/wɛl/","gloss":"bem"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"gives","pos":"verb","ipa":"/ɡɪvz/","gloss":"dá"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"energy","pos":"noun","ipa":"/ˈɛnərdʒi/","gloss":"energia"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"things","pos":"noun","ipa":"/θɪŋz/","gloss":"coisas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"enjoy","pos":"verb","ipa":"/ɪnˈdʒɔɪ/","gloss":"aproveitar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-03-05', 'lesson-paragraphs-b2-03', 5, 'paragraph', 'The food is another reason to visit. Local restaurants serve fresh fish, and the bakeries open before sunrise.', 'A comida é outro motivo para visitar. Os restaurantes locais servem peixe fresco, e as padarias abrem antes do nascer do sol.', '/ðə fuːd ɪz əˈnʌðər ˈriːzən tuː ˈvɪzɪt ˈloʊkəl ˈrɛstərɑːnts sɜːrv frɛʃ fɪʃ ænd ðə ˈbeɪkəriz ˈoʊpən bɪˈfɔːr ˈsʌnraɪz/', '"Another reason" acrescenta um argumento à descrição.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"food","pos":"noun","ipa":"/fuːd/","gloss":"comida"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"reason","pos":"noun","ipa":"/ˈriːzən/","gloss":"motivo, razão"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"visit","pos":"noun","ipa":"/ˈvɪzɪt/","gloss":"visita"},{"surface":"Local","pos":"adjective","ipa":"/ˈloʊkəl/","gloss":"local"},{"surface":"restaurants","pos":"noun","ipa":"/ˈrɛstərɑːnts/","gloss":"restaurantes"},{"surface":"serve","pos":"verb","ipa":"/sɜːrv/","gloss":"servir"},{"surface":"fresh","pos":"adjective","ipa":"/frɛʃ/","gloss":"fresco"},{"surface":"fish","pos":"noun","ipa":"/fɪʃ/","gloss":"peixe"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bakeries","pos":"noun","ipa":"/ˈbeɪkəriz/","gloss":"padarias"},{"surface":"open","pos":"verb","ipa":"/ˈoʊpən/","gloss":"abrir"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"sunrise","pos":"noun","ipa":"/ˈsʌnraɪz/","gloss":"nascer do sol"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-03-06', 'lesson-paragraphs-b2-03', 6, 'paragraph', 'In summer, the city hosts a music festival that lasts three days. Thousands of visitors come, so hotels fill up quickly.', 'No verão, a cidade recebe um festival de música que dura três dias. Milhares de visitantes vêm, então os hotéis lotam rapidamente.', '/ɪn ˈsʌmər ðə ˈsɪti hoʊsts ə ˈmjuːzɪk ˈfɛstəvəl ðæt læsts θriː deɪz ˈθaʊzəndz ʌv ˈvɪzɪtərz kʌm soʊ hoʊˈtɛlz fɪl ʌp ˈkwɪkli/', '"That" abre uma oração relativa. "Fill up" = lotar.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"summer","pos":"noun","ipa":"/ˈsʌmər/","gloss":"verão"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"},{"surface":"hosts","pos":"verb","ipa":"/hoʊsts/","gloss":"recebe, sedia"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"music","pos":"noun","ipa":"/ˈmjuːzɪk/","gloss":"música"},{"surface":"festival","pos":"noun","ipa":"/ˈfɛstəvəl/","gloss":"festival"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"lasts","pos":"verb","ipa":"/læsts/","gloss":"dura"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"},{"surface":"days","pos":"noun","ipa":"/deɪz/","gloss":"dias"},{"surface":"Thousands","pos":"noun","ipa":"/ˈθaʊzəndz/","gloss":"milhares"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"visitors","pos":"noun","ipa":"/ˈvɪzɪtərz/","gloss":"visitantes"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"hotels","pos":"noun","ipa":"/hoʊˈtɛlz/","gloss":"hotéis"},{"surface":"fill","pos":"verb","ipa":"/fɪl/","gloss":"preencher; obturar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"quickly","pos":"adverb","ipa":"/ˈkwɪkli/","gloss":"rapidamente"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-03-07', 'lesson-paragraphs-b2-03', 7, 'paragraph', 'Because of the tourists, prices have gone up in recent years. Some residents are worried that the old town is losing its character.', 'Por causa dos turistas, os preços subiram nos últimos anos. Alguns moradores temem que o centro histórico esteja perdendo o caráter.', '/bɪˈkɔːz ʌv ðə ˈtʊrɪsts ˈpraɪsɪz hæv ɡɔːn ʌp ɪn ˈriːsənt jɪrz sʌm ˈrɛzɪdənts ɑːr ˈwɜːrid ðæt ðə oʊld taʊn ɪz ˈluːzɪŋ ɪts ˈkærɪktər/', '"Because of" + substantivo. Present perfect para mudança até agora.', '[]'::jsonb, '[{"surface":"Because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"tourists","pos":"noun","ipa":"/ˈtʊrɪsts/","gloss":"turistas"},{"surface":"prices","pos":"noun","ipa":"/ˈpraɪsɪz/","gloss":"preços"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"gone","pos":"verb","ipa":"/ɡɔːn/","gloss":"ido (particípio de go)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"recent","pos":"adjective","ipa":"/ˈriːsənt/","gloss":"recente"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"},{"surface":"Some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"residents","pos":"noun","ipa":"/ˈrɛzɪdənts/","gloss":"moradores"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"worried","pos":"adjective","ipa":"/ˈwɜːrid/","gloss":"preocupado"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"town","pos":"noun","ipa":"/taʊn/","gloss":"cidade pequena"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"losing","pos":"verb","ipa":"/ˈluːzɪŋ/","gloss":"perdendo"},{"surface":"its","pos":"determiner","ipa":"/ɪts/","gloss":"seu, sua (de coisa)"},{"surface":"character","pos":"noun","ipa":"/ˈkærɪktər/","gloss":"caráter, personalidade"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-03-08', 'lesson-paragraphs-b2-03', 8, 'paragraph', 'Even so, I would not live anywhere else. The people are friendly, and the mountains are always there when I need peace.', 'Mesmo assim, eu não moraria em outro lugar. As pessoas são simpáticas, e as montanhas estão sempre lá quando preciso de paz.', '/ˈiːvən soʊ aɪ wʊd nɑːt lɪv ˈɛniwɛr ɛls ðə ˈpiːpəl ɑːr ˈfrɛndli ænd ðə ˈmaʊntənz ɑːr ˈɔːlweɪz ðɛr wɛn aɪ niːd piːs/', '"Even so" retoma o lado positivo. "Would not live anywhere else" = escolha firme.', '[]'::jsonb, '[{"surface":"Even","pos":"adverb","ipa":"/ˈiːvən/","gloss":"até, mesmo"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"live","pos":"verb","ipa":"/lɪv/","gloss":"morar, viver"},{"surface":"anywhere","pos":"adverb","ipa":"/ˈɛniwɛr/","gloss":"em qualquer lugar"},{"surface":"else","pos":"adverb","ipa":"/ɛls/","gloss":"mais, outro"},{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"friendly","pos":"adjective","ipa":"/ˈfrɛndli/","gloss":"simpático"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"mountains","pos":"noun","ipa":"/ˈmaʊntənz/","gloss":"montanhas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"peace","pos":"noun","ipa":"/piːs/","gloss":"paz"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-04-05', 'lesson-paragraphs-b2-04', 5, 'paragraph', 'After the mechanic fixed the car, we continued along the coast. The roads were narrow, but the views were incredible.', 'Depois que o mecânico consertou o carro, seguimos pelo litoral. As estradas eram estreitas, mas as paisagens eram incríveis.', '/ˈæftər ðə məˈkænɪk fɪkst ðə kɑːr wiː kənˈtɪnjuːd əˈlɔːŋ ðə koʊst ðə roʊdz wɜːr ˈnæroʊ bʌt ðə vjuːz wɜːr ɪnˈkrɛdəbəl/', 'Sequência no passado com "after". Contraste com "but".', '[]'::jsonb, '[{"surface":"After","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"mechanic","pos":"noun","ipa":"/məˈkænɪk/","gloss":"mecânico"},{"surface":"fixed","pos":"verb","ipa":"/fɪkst/","gloss":"consertado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"continued","pos":"verb","ipa":"/kənˈtɪnjuːd/","gloss":"continuou"},{"surface":"along","pos":"particle","ipa":"/əˈlɔːŋ/","gloss":"junto (get along = dar-se bem)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"coast","pos":"noun","ipa":"/koʊst/","gloss":"litoral"},{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"roads","pos":"noun","ipa":"/roʊdz/","gloss":"estradas"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"narrow","pos":"adjective","ipa":"/ˈnæroʊ/","gloss":"estreito"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"views","pos":"noun","ipa":"/vjuːz/","gloss":"paisagens, vistas"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"incredible","pos":"adjective","ipa":"/ɪnˈkrɛdəbəl/","gloss":"incrível"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-04-06', 'lesson-paragraphs-b2-04', 6, 'paragraph', 'In a small fishing town, we stayed in a guesthouse run by an old couple. They told us stories about the sea every evening.', 'Numa pequena cidade de pescadores, ficamos numa pousada administrada por um casal de idosos. Eles nos contavam histórias do mar toda noite.', '/ɪn ə smɔːl ˈfɪʃɪŋ taʊn wiː steɪd ɪn ə ˈɡɛsthaʊs rʌn baɪ ən oʊld ˈkʌpəl ðeɪ toʊld ʌs ˈstɔːriz əˈbaʊt ðə siː ˈɛvri ˈiːvnɪŋ/', '"Run by" = administrada por (voz passiva reduzida). "Told us" + objeto indireto.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"fishing","pos":"noun","ipa":"/ˈfɪʃɪŋ/","gloss":"pesca"},{"surface":"town","pos":"noun","ipa":"/taʊn/","gloss":"cidade pequena"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"stayed","pos":"verb","ipa":"/steɪd/","gloss":"ficou"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"guesthouse","pos":"noun","ipa":"/ˈɡɛsthaʊs/","gloss":"pousada"},{"surface":"run","pos":"verb","ipa":"/rʌn/","gloss":"correr; administrar"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"couple","pos":"noun","ipa":"/ˈkʌpəl/","gloss":"casal"},{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"stories","pos":"noun","ipa":"/ˈstɔːriz/","gloss":"histórias"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"sea","pos":"noun","ipa":"/siː/","gloss":"mar"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"evening","pos":"noun","ipa":"/ˈiːvnɪŋ/","gloss":"noite (início), fim de tarde"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-04-07', 'lesson-paragraphs-b2-04', 7, 'paragraph', 'On the last day, we climbed a hill to watch the sunset. Nobody spoke for a while because it was so beautiful.', 'No último dia, subimos uma colina para ver o pôr do sol. Ninguém falou por um tempo porque era lindo demais.', '/ɑːn ðə læst deɪ wiː klaɪmd ə hɪl tuː wɑːtʃ ðə ˈsʌnsɛt ˈnoʊbɑːdi spoʊk fɔːr ə waɪl bɪˈkɔːz ɪt wɑːz soʊ ˈbjuːtɪfəl/', '"To watch" = finalidade. "So + adjetivo" dá ênfase.', '[]'::jsonb, '[{"surface":"On","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"climbed","pos":"verb","ipa":"/klaɪmd/","gloss":"subiu"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"hill","pos":"noun","ipa":"/hɪl/","gloss":"colina"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"watch","pos":"noun","ipa":"/wɑːtʃ/","gloss":"relógio de pulso"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"sunset","pos":"noun","ipa":"/ˈsʌnsɛt/","gloss":"pôr do sol"},{"surface":"Nobody","pos":"pronoun","ipa":"/ˈnoʊbɑːdi/","gloss":"ninguém"},{"surface":"spoke","pos":"verb","ipa":"/spoʊk/","gloss":"falou"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"while","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"beautiful","pos":"adjective","ipa":"/ˈbjuːtɪfəl/","gloss":"bonito, lindo"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-04-08', 'lesson-paragraphs-b2-04', 8, 'paragraph', 'When we got home, we printed our favorite photos. I still keep one on my desk to remind me of that trip.', 'Quando chegamos em casa, imprimimos nossas fotos favoritas. Ainda guardo uma na minha mesa para me lembrar daquela viagem.', '/wɛn wiː ɡɑːt hoʊm wiː ˈprɪntɪd aʊər ˈfeɪvərɪt ˈfoʊtoʊz aɪ stɪl kiːp wʌn ɑːn maɪ dɛsk tuː rɪˈmaɪnd miː ʌv ðæt trɪp/', 'Fecha a narrativa voltando ao presente com "still". "Remind me of" = me lembrar de.', '[]'::jsonb, '[{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"printed","pos":"verb","ipa":"/ˈprɪntɪd/","gloss":"imprimiu"},{"surface":"our","pos":"determiner","ipa":"/aʊər/","gloss":"nosso"},{"surface":"favorite","pos":"adjective","ipa":"/ˈfeɪvərɪt/","gloss":"favorito"},{"surface":"photos","pos":"noun","ipa":"/ˈfoʊtoʊz/","gloss":"fotos"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"still","pos":"adverb","ipa":"/stɪl/","gloss":"ainda"},{"surface":"keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"desk","pos":"noun","ipa":"/dɛsk/","gloss":"escrivaninha"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"remind","pos":"verb","ipa":"/rɪˈmaɪnd/","gloss":"lembrar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"trip","pos":"noun","ipa":"/trɪp/","gloss":"viagem"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-05-05', 'lesson-paragraphs-b2-05', 5, 'paragraph', 'Another advantage is flexibility. Parents can adjust their schedules to pick up their children from school.', 'Outra vantagem é a flexibilidade. Pais podem ajustar seus horários para buscar os filhos na escola.', '/əˈnʌðər ədˈvæntɪdʒ ɪz ˌflɛksəˈbɪləti ˈpɛrənts kæn əˈdʒʌst ðɛr ˈskɛdʒuːlz tuː pɪk ʌp ðɛr ˈtʃɪldrən frʌm skuːl/', '"Another advantage" acrescenta um argumento. "Pick up" = buscar.', '[]'::jsonb, '[{"surface":"Another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"advantage","pos":"noun","ipa":"/ədˈvæntɪdʒ/","gloss":"vantagem"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"flexibility","pos":"noun","ipa":"/ˌflɛksəˈbɪləti/","gloss":"flexibilidade"},{"surface":"Parents","pos":"noun","ipa":"/ˈpɛrənts/","gloss":"pais (pai e mãe)"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"adjust","pos":"verb","ipa":"/əˈdʒʌst/","gloss":"ajustar"},{"surface":"their","pos":"determiner","ipa":"/ðɛr/","gloss":"deles, delas"},{"surface":"schedules","pos":"noun","ipa":"/ˈskɛdʒuːlz/","gloss":"horários"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"pick","pos":"verb","ipa":"/pɪk/","gloss":"pegar (pick up)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"their","pos":"determiner","ipa":"/ðɛr/","gloss":"deles, delas"},{"surface":"children","pos":"noun","ipa":"/ˈtʃɪldrən/","gloss":"crianças, filhos"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"school","pos":"noun","ipa":"/skuːl/","gloss":"escola"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-05-06', 'lesson-paragraphs-b2-05', 6, 'paragraph', 'Some managers worry that teams work less when nobody is watching. However, studies show that many people are actually more productive at home.', 'Alguns gerentes temem que as equipes trabalhem menos quando ninguém está olhando. No entanto, estudos mostram que muitas pessoas são, na verdade, mais produtivas em casa.', '/sʌm ˈmænɪdʒərz ˈwɜːri ðæt tiːmz wɜːrk lɛs wɛn ˈnoʊbɑːdi ɪz ˈwɑːtʃɪŋ haʊˈɛvər ˈstʌdiz ʃoʊ ðæt ˈmɛni ˈpiːpəl ɑːr ˈæktʃuəli mɔːr prəˈdʌktɪv æt hoʊm/', 'Apresenta a objeção e a rebate com "however". "Actually" = na verdade.', '[]'::jsonb, '[{"surface":"Some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"managers","pos":"noun","ipa":"/ˈmænɪdʒərz/","gloss":"gerentes"},{"surface":"worry","pos":"verb","ipa":"/ˈwɜːri/","gloss":"se preocupar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"teams","pos":"noun","ipa":"/tiːmz/","gloss":"equipes"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"less","pos":"determiner","ipa":"/lɛs/","gloss":"menos"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"nobody","pos":"pronoun","ipa":"/ˈnoʊbɑːdi/","gloss":"ninguém"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"watching","pos":"verb","ipa":"/ˈwɑːtʃɪŋ/","gloss":"olhando, assistindo"},{"surface":"However","pos":"adverb","ipa":"/haʊˈɛvər/","gloss":"no entanto, mesmo assim"},{"surface":"studies","pos":"verb","ipa":"/ˈstʌdiz/","gloss":"estuda"},{"surface":"show","pos":"verb","ipa":"/ʃoʊ/","gloss":"aparecer (show up)"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"actually","pos":"adverb","ipa":"/ˈæktʃuəli/","gloss":"na verdade"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"productive","pos":"adjective","ipa":"/prəˈdʌktɪv/","gloss":"produtivo"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-05-07', 'lesson-paragraphs-b2-05', 7, 'paragraph', 'Nevertheless, remote work is not suitable for every job. Doctors, teachers and builders, for example, must be physically present.', 'Mesmo assim, o trabalho remoto não serve para todas as profissões. Médicos, professores e pedreiros, por exemplo, precisam estar presentes.', '/ˌnɛvərðəˈlɛs rɪˈmoʊt wɜːrk ɪz nɑːt ˈsuːtəbəl fɔːr ˈɛvri dʒɑːb ˈdɑːktərz ˈtiːtʃərz ænd ˈbɪldərz fɔːr ɪɡˈzæmpəl mʌst biː ˈfɪzɪkli ˈprɛzənt/', '"Nevertheless" = ainda assim; mais formal que "but". "For example" no meio da frase.', '[]'::jsonb, '[{"surface":"Nevertheless","pos":"adverb","ipa":"/ˌnɛvərðəˈlɛs/","gloss":"no entanto"},{"surface":"remote","pos":"adjective","ipa":"/rɪˈmoʊt/","gloss":"remoto"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"suitable","pos":"adjective","ipa":"/ˈsuːtəbəl/","gloss":"adequado"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"Doctors","pos":"noun","ipa":"/ˈdɑːktərz/","gloss":"médicos"},{"surface":"teachers","pos":"noun","ipa":"/ˈtiːtʃərz/","gloss":"professores"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"builders","pos":"noun","ipa":"/ˈbɪldərz/","gloss":"pedreiros, construtores"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"example","pos":"noun","ipa":"/ɪɡˈzæmpəl/","gloss":"exemplo"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"physically","pos":"adverb","ipa":"/ˈfɪzɪkli/","gloss":"fisicamente"},{"surface":"present","pos":"adjective","ipa":"/ˈprɛzənt/","gloss":"presente"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-05-08', 'lesson-paragraphs-b2-05', 8, 'paragraph', 'To sum up, working from home is a useful option, not a solution for everyone. What matters most is that people have a real choice.', 'Resumindo, trabalhar de casa é uma opção útil, não uma solução para todos. O mais importante é que as pessoas tenham uma escolha real.', '/tuː sʌm ʌp ˈwɜːrkɪŋ frʌm hoʊm ɪz ə ˈjuːsfəl ˈɑːpʃən nɑːt ə səˈluːʃən fɔːr ˈɛvriwʌn wʌt ˈmætərz moʊst ɪz ðæt ˈpiːpəl hæv ə ˈriːəl tʃɔɪs/', '"To sum up" fecha. "What matters most is" destaca a ideia final.', '[]'::jsonb, '[{"surface":"To","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"sum","pos":"verb","ipa":"/sʌm/","gloss":"somar, resumir"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"useful","pos":"adjective","ipa":"/ˈjuːsfəl/","gloss":"útil"},{"surface":"option","pos":"noun","ipa":"/ˈɑːpʃən/","gloss":"opção"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"solution","pos":"noun","ipa":"/səˈluːʃən/","gloss":"solução"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"everyone","pos":"pronoun","ipa":"/ˈɛvriwʌn/","gloss":"todo mundo, pessoal"},{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"matters","pos":"verb","ipa":"/ˈmætərz/","gloss":"importa"},{"surface":"most","pos":"determiner","ipa":"/moʊst/","gloss":"o máximo, a maioria"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"real","pos":"adjective","ipa":"/ˈriːəl/","gloss":"real"},{"surface":"choice","pos":"noun","ipa":"/tʃɔɪs/","gloss":"escolha"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-06-05', 'lesson-paragraphs-b2-06', 5, 'paragraph', 'I first contacted your customer service team by phone on the third of the month. The agent promised to call me back, but nobody did.', 'Entrei em contato com o atendimento de vocês por telefone no dia três do mês. O atendente prometeu retornar, mas ninguém retornou.', '/aɪ fɜːrst ˈkɑːntæktɪd jʊr ˈkʌstəmər ˈsɜːrvɪs tiːm baɪ foʊn ɑːn ðə θɜːrd ʌv ðə mʌnθ ðə ˈeɪdʒənt ˈprɑːmɪst tuː kɔːl miː bæk bʌt ˈnoʊbɑːdi dɪd/', 'Relata o histórico no passado. "Call back" = retornar a ligação.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"contacted","pos":"verb","ipa":"/ˈkɑːntæktɪd/","gloss":"entrou em contato"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"customer","pos":"noun","ipa":"/ˈkʌstəmər/","gloss":"cliente"},{"surface":"service","pos":"noun","ipa":"/ˈsɜːrvɪs/","gloss":"serviço"},{"surface":"team","pos":"noun","ipa":"/tiːm/","gloss":"time, equipe"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"third","pos":"adjective","ipa":"/θɜːrd/","gloss":"terceiro"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"},{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"agent","pos":"noun","ipa":"/ˈeɪdʒənt/","gloss":"atendente, agente"},{"surface":"promised","pos":"verb","ipa":"/ˈprɑːmɪst/","gloss":"prometeu"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"nobody","pos":"pronoun","ipa":"/ˈnoʊbɑːdi/","gloss":"ninguém"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-06-06', 'lesson-paragraphs-b2-06', 6, 'paragraph', 'This is the second time I have had a problem with your company. I have always been a satisfied customer, so I am disappointed.', 'Esta é a segunda vez que tenho um problema com a empresa de vocês. Sempre fui um cliente satisfeito, por isso estou decepcionado.', '/ðɪs ɪz ðə ˈsɛkənd taɪm aɪ hæv hæd ə ˈprɑːbləm wɪð jʊr ˈkʌmpəni aɪ hæv ˈɔːlweɪz bɪn ə ˈsætɪsfaɪd ˈkʌstəmər soʊ aɪ æm ˌdɪsəˈpɔɪntɪd/', 'Present perfect para a experiência até agora. "So" liga causa e consequência.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"second","pos":"adjective","ipa":"/ˈsɛkənd/","gloss":"segundo"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"company","pos":"noun","ipa":"/ˈkʌmpəni/","gloss":"empresa"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"satisfied","pos":"adjective","ipa":"/ˈsætɪsfaɪd/","gloss":"satisfeito"},{"surface":"customer","pos":"noun","ipa":"/ˈkʌstəmər/","gloss":"cliente"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"disappointed","pos":"adjective","ipa":"/ˌdɪsəˈpɔɪntɪd/","gloss":"decepcionado"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-06-07', 'lesson-paragraphs-b2-06', 7, 'paragraph', 'If I do not receive an answer within seven days, I will have to contact a consumer protection office. I would prefer to solve this directly with you.', 'Se eu não receber uma resposta em até sete dias, terei que procurar um órgão de defesa do consumidor. Preferiria resolver isso diretamente com vocês.', '/ɪf aɪ duː nɑːt rɪˈsiːv ən ˈænsər wɪˈðɪn ˈsɛvən deɪz aɪ wɪl hæv tuː ˈkɑːntækt ə kənˈsuːmər prəˈtɛkʃən ˈɔːfɪs aɪ wʊd prɪˈfɜːr tuː sɑːlv ðɪs dəˈrɛktli wɪð juː/', 'Primeira condicional como aviso firme e educado. "Would prefer" suaviza.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"receive","pos":"verb","ipa":"/rɪˈsiːv/","gloss":"receber"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"answer","pos":"noun","ipa":"/ˈænsər/","gloss":"resposta"},{"surface":"within","pos":"preposition","ipa":"/wɪˈðɪn/","gloss":"dentro de"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"},{"surface":"days","pos":"noun","ipa":"/deɪz/","gloss":"dias"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"contact","pos":"verb","ipa":"/ˈkɑːntækt/","gloss":"contatar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"consumer","pos":"noun","ipa":"/kənˈsuːmər/","gloss":"consumidor"},{"surface":"protection","pos":"noun","ipa":"/prəˈtɛkʃən/","gloss":"proteção, defesa"},{"surface":"office","pos":"noun","ipa":"/ˈɔːfɪs/","gloss":"escritório, balcão"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"prefer","pos":"verb","ipa":"/prɪˈfɜːr/","gloss":"preferir"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"solve","pos":"verb","ipa":"/sɑːlv/","gloss":"resolver"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"directly","pos":"adverb","ipa":"/dəˈrɛktli/","gloss":"diretamente"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-06-08', 'lesson-paragraphs-b2-06', 8, 'paragraph', 'Thank you for your time and attention to this matter. Please find my order number and contact details below.', 'Obrigado pelo seu tempo e atenção a este assunto. Seguem abaixo o número do pedido e meus dados de contato.', '/θæŋk juː fɔːr jʊr taɪm ænd əˈtɛnʃən tuː ðɪs ˈmætər pliːz faɪnd maɪ ˈɔːrdər ˈnʌmbər ænd ˈkɑːntækt ˈdiːteɪlz bɪˈloʊ/', '"Please find ... below" = fórmula de e-mail formal.', '[]'::jsonb, '[{"surface":"Thank","pos":"verb","ipa":"/θæŋk/","gloss":"agradecer"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"attention","pos":"noun","ipa":"/əˈtɛnʃən/","gloss":"atenção"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"matter","pos":"noun","ipa":"/ˈmætər/","gloss":"questão, assunto"},{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"find","pos":"verb","ipa":"/faɪnd/","gloss":"encontrar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"order","pos":"verb","ipa":"/ˈɔːrdər/","gloss":"pedir (comida)"},{"surface":"number","pos":"noun","ipa":"/ˈnʌmbər/","gloss":"número"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"contact","pos":"verb","ipa":"/ˈkɑːntækt/","gloss":"contatar"},{"surface":"details","pos":"noun","ipa":"/ˈdiːteɪlz/","gloss":"detalhes"},{"surface":"below","pos":"preposition","ipa":"/bɪˈloʊ/","gloss":"abaixo de"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-07-05', 'lesson-paragraphs-b2-07', 5, 'paragraph', 'The story follows the family during one difficult winter. When the bakery is about to close, they must decide whether to sell it.', 'A história acompanha a família durante um inverno difícil. Quando a padaria está prestes a fechar, eles precisam decidir se vão vendê-la.', '/ðə ˈstɔːri ˈfɑːloʊz ðə ˈfæməli ˈdʊrɪŋ wʌn ˈdɪfɪkəlt ˈwɪntər wɛn ðə ˈbeɪkəri ɪz əˈbaʊt tuː kloʊz ðeɪ mʌst dɪˈsaɪd ˈwɛðər tuː sɛl ɪt/', '"Be about to" = estar prestes a. "Whether" introduz uma dúvida.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"story","pos":"noun","ipa":"/ˈstɔːri/","gloss":"história"},{"surface":"follows","pos":"verb","ipa":"/ˈfɑːloʊz/","gloss":"acompanha, segue"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"family","pos":"noun","ipa":"/ˈfæməli/","gloss":"família"},{"surface":"during","pos":"preposition","ipa":"/ˈdʊrɪŋ/","gloss":"durante"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"difficult","pos":"adjective","ipa":"/ˈdɪfɪkəlt/","gloss":"difícil"},{"surface":"winter","pos":"noun","ipa":"/ˈwɪntər/","gloss":"inverno"},{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bakery","pos":"noun","ipa":"/ˈbeɪkəri/","gloss":"padaria"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"close","pos":"verb","ipa":"/kloʊz/","gloss":"fechar"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"decide","pos":"verb","ipa":"/dɪˈsaɪd/","gloss":"decidir"},{"surface":"whether","pos":"conjunction","ipa":"/ˈwɛðər/","gloss":"se (dúvida)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"sell","pos":"verb","ipa":"/sɛl/","gloss":"vender"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-07-06', 'lesson-paragraphs-b2-07', 6, 'paragraph', 'The photography deserves special mention. Every scene seems lit by the morning sun, which makes the bread look delicious.', 'A fotografia merece menção especial. Cada cena parece iluminada pelo sol da manhã, o que faz o pão parecer delicioso.', '/ðə fəˈtɑːɡrəfi dɪˈzɜːrvz ˈspɛʃəl ˈmɛnʃən ˈɛvri siːn siːmz lɪt baɪ ðə ˈmɔːrnɪŋ sʌn wɪtʃ meɪks ðə brɛd lʊk dɪˈlɪʃəs/', '"Which" retoma a frase inteira. "Make + objeto + verbo" sem "to".', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"photography","pos":"noun","ipa":"/fəˈtɑːɡrəfi/","gloss":"fotografia"},{"surface":"deserves","pos":"verb","ipa":"/dɪˈzɜːrvz/","gloss":"merece"},{"surface":"special","pos":"adjective","ipa":"/ˈspɛʃəl/","gloss":"especial"},{"surface":"mention","pos":"noun","ipa":"/ˈmɛnʃən/","gloss":"menção"},{"surface":"Every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"scene","pos":"noun","ipa":"/siːn/","gloss":"cena"},{"surface":"seems","pos":"verb","ipa":"/siːmz/","gloss":"parece"},{"surface":"lit","pos":"adjective","ipa":"/lɪt/","gloss":"iluminado"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"},{"surface":"sun","pos":"noun","ipa":"/sʌn/","gloss":"sol"},{"surface":"which","pos":"determiner","ipa":"/wɪtʃ/","gloss":"qual"},{"surface":"makes","pos":"verb","ipa":"/meɪks/","gloss":"faz"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bread","pos":"noun","ipa":"/brɛd/","gloss":"pão"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"delicious","pos":"adjective","ipa":"/dɪˈlɪʃəs/","gloss":"delicioso"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-07-07', 'lesson-paragraphs-b2-07', 7, 'paragraph', 'I also liked the music, which is quiet and never takes over. It supports the emotion instead of telling you how to feel.', 'Gostei também da música, que é tranquila e nunca domina a cena. Ela apoia a emoção em vez de dizer como você deve se sentir.', '/aɪ ˈɔːlsoʊ laɪkt ðə ˈmjuːzɪk wɪtʃ ɪz ˈkwaɪət ænd ˈnɛvər teɪks ˈoʊvər ɪt səˈpɔːrts ðə ɪˈmoʊʃən ɪnˈstɛd ʌv ˈtɛlɪŋ juː haʊ tuː fiːl/', '"Instead of" + -ing. "Take over" = dominar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"also","pos":"adverb","ipa":"/ˈɔːlsoʊ/","gloss":"também"},{"surface":"liked","pos":"verb","ipa":"/laɪkt/","gloss":"gostou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"music","pos":"noun","ipa":"/ˈmjuːzɪk/","gloss":"música"},{"surface":"which","pos":"determiner","ipa":"/wɪtʃ/","gloss":"qual"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"quiet","pos":"adjective","ipa":"/ˈkwaɪət/","gloss":"quieto"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"takes","pos":"verb","ipa":"/teɪks/","gloss":"pega, leva; decola"},{"surface":"over","pos":"preposition","ipa":"/ˈoʊvər/","gloss":"por cima; superado"},{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"supports","pos":"verb","ipa":"/səˈpɔːrts/","gloss":"apoia"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"emotion","pos":"noun","ipa":"/ɪˈmoʊʃən/","gloss":"emoção"},{"surface":"instead","pos":"adverb","ipa":"/ɪnˈstɛd/","gloss":"em vez disso"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"telling","pos":"verb","ipa":"/ˈtɛlɪŋ/","gloss":"contando"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"how","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-07-08', 'lesson-paragraphs-b2-07', 8, 'paragraph', 'I recommend it to anyone who enjoys slow, human stories. If you want action, however, you should choose something else.', 'Recomendo a quem gosta de histórias lentas e humanas. Se você quer ação, porém, deve escolher outro filme.', '/aɪ ˌrɛkəˈmɛnd ɪt tuː ˈɛniwʌn huː ɪnˈdʒɔɪz sloʊ ˈhjuːmən ˈstɔːriz ɪf juː wɑːnt ˈækʃən haʊˈɛvər juː ʃʊd tʃuːz ˈsʌmθɪŋ ɛls/', 'Recomendação com ressalva. "However" no meio da frase, entre vírgulas.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"recommend","pos":"verb","ipa":"/ˌrɛkəˈmɛnd/","gloss":"recomendar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"anyone","pos":"pronoun","ipa":"/ˈɛniwʌn/","gloss":"alguém, ninguém"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"enjoys","pos":"verb","ipa":"/ɪnˈdʒɔɪz/","gloss":"gosta, aproveita"},{"surface":"slow","pos":"adjective","ipa":"/sloʊ/","gloss":"lento"},{"surface":"human","pos":"adjective","ipa":"/ˈhjuːmən/","gloss":"humano"},{"surface":"stories","pos":"noun","ipa":"/ˈstɔːriz/","gloss":"histórias"},{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"},{"surface":"action","pos":"noun","ipa":"/ˈækʃən/","gloss":"ação"},{"surface":"however","pos":"adverb","ipa":"/haʊˈɛvər/","gloss":"no entanto, mesmo assim"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"choose","pos":"verb","ipa":"/tʃuːz/","gloss":"escolher"},{"surface":"something","pos":"pronoun","ipa":"/ˈsʌmθɪŋ/","gloss":"alguma coisa"},{"surface":"else","pos":"adverb","ipa":"/ɛls/","gloss":"mais, outro"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-08-05', 'lesson-paragraphs-b2-08', 5, 'paragraph', 'If the crust is too pale, put the loaf back in the oven for five more minutes. A little steam in the oven helps it turn golden.', 'Se a casca estiver muito clara, coloque o pão de volta no forno por mais cinco minutos. Um pouco de vapor no forno ajuda a dourar.', '/ɪf ðə krʌst ɪz tuː peɪl pʊt ðə loʊf bæk ɪn ðə ˈʌvən fɔːr faɪv mɔːr ˈmɪnɪts ə ˈlɪtəl stiːm ɪn ðə ˈʌvən hɛlps ɪt tɜːrn ˈɡoʊldən/', 'Imperativo com "if". "Turn golden" = ficar dourado.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"crust","pos":"noun","ipa":"/krʌst/","gloss":"casca (do pão)"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"pale","pos":"adjective","ipa":"/peɪl/","gloss":"claro, pálido"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"loaf","pos":"noun","ipa":"/loʊf/","gloss":"pão (unidade)"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"oven","pos":"noun","ipa":"/ˈʌvən/","gloss":"forno"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"minutes","pos":"noun","ipa":"/ˈmɪnɪts/","gloss":"minutos"},{"surface":"A","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"little","pos":"adjective","ipa":"/ˈlɪtəl/","gloss":"pouco, pequeno"},{"surface":"steam","pos":"noun","ipa":"/stiːm/","gloss":"vapor"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"oven","pos":"noun","ipa":"/ˈʌvən/","gloss":"forno"},{"surface":"helps","pos":"verb","ipa":"/hɛlps/","gloss":"ajuda"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"turn","pos":"verb","ipa":"/tɜːrn/","gloss":"ligar (turn on)"},{"surface":"golden","pos":"adjective","ipa":"/ˈɡoʊldən/","gloss":"dourado"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-08-06', 'lesson-paragraphs-b2-08', 6, 'paragraph', 'Do not worry if your first loaf is not perfect. Practice matters more than a perfect recipe.', 'Não se preocupe se o primeiro pão não ficar perfeito. A prática importa mais que uma receita perfeita.', '/duː nɑːt ˈwɜːri ɪf jʊr fɜːrst loʊf ɪz nɑːt ˈpɜːrfɪkt ˈpræktɪs ˈmætərz mɔːr ðæn ə ˈpɜːrfɪkt ˈrɛsəpi/', 'Tranquiliza o leitor. "More than" compara.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"worry","pos":"verb","ipa":"/ˈwɜːri/","gloss":"se preocupar"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"loaf","pos":"noun","ipa":"/loʊf/","gloss":"pão (unidade)"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"perfect","pos":"adjective","ipa":"/ˈpɜːrfɪkt/","gloss":"perfeito"},{"surface":"Practice","pos":"noun","ipa":"/ˈpræktɪs/","gloss":"prática"},{"surface":"matters","pos":"verb","ipa":"/ˈmætərz/","gloss":"importa"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"perfect","pos":"adjective","ipa":"/ˈpɜːrfɪkt/","gloss":"perfeito"},{"surface":"recipe","pos":"noun","ipa":"/ˈrɛsəpi/","gloss":"receita"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-08-07', 'lesson-paragraphs-b2-08', 7, 'paragraph', 'You can also add seeds, nuts or herbs to the dough. Just remember to mix them in before the first rest.', 'Você também pode acrescentar sementes, castanhas ou ervas à massa. Só lembre de misturá-las antes do primeiro descanso.', '/juː kæn ˈɔːlsoʊ æd siːdz nʌts ɔːr ɜːrbz tuː ðə doʊ dʒʌst rɪˈmɛmbər tuː mɪks ðɛm ɪn bɪˈfɔːr ðə fɜːrst rɛst/', '"Remember to" + verbo = não esquecer de fazer. "Mix in" = incorporar.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"also","pos":"adverb","ipa":"/ˈɔːlsoʊ/","gloss":"também"},{"surface":"add","pos":"verb","ipa":"/æd/","gloss":"acrescentar"},{"surface":"seeds","pos":"noun","ipa":"/siːdz/","gloss":"sementes"},{"surface":"nuts","pos":"noun","ipa":"/nʌts/","gloss":"castanhas, nozes"},{"surface":"or","pos":"conjunction","ipa":"/ɔːr/","gloss":"ou"},{"surface":"herbs","pos":"noun","ipa":"/ɜːrbz/","gloss":"ervas"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"dough","pos":"noun","ipa":"/doʊ/","gloss":"massa"},{"surface":"Just","pos":"adverb","ipa":"/dʒʌst/","gloss":"só, apenas"},{"surface":"remember","pos":"verb","ipa":"/rɪˈmɛmbər/","gloss":"lembrar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"mix","pos":"verb","ipa":"/mɪks/","gloss":"misturar"},{"surface":"them","pos":"pronoun","ipa":"/ðɛm/","gloss":"eles, os"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"rest","pos":"verb","ipa":"/rɛst/","gloss":"descansar"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-08-08', 'lesson-paragraphs-b2-08', 8, 'paragraph', 'Fresh bread is best on the same day, but it also freezes well. Slice it first, so you can take out only what you need.', 'O pão fresco é melhor no mesmo dia, mas também congela bem. Fatie primeiro, para tirar só o que for usar.', '/frɛʃ brɛd ɪz bɛst ɑːn ðə seɪm deɪ bʌt ɪt ˈɔːlsoʊ ˈfriːzɪz wɛl slaɪs ɪt fɜːrst soʊ juː kæn teɪk aʊt ˈoʊnli wʌt juː niːd/', '"Best" = superlativo. "So you can" = para que você possa.', '[]'::jsonb, '[{"surface":"Fresh","pos":"adjective","ipa":"/frɛʃ/","gloss":"fresco"},{"surface":"bread","pos":"noun","ipa":"/brɛd/","gloss":"pão"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"best","pos":"adjective","ipa":"/bɛst/","gloss":"melhor"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"same","pos":"adjective","ipa":"/seɪm/","gloss":"mesmo"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"also","pos":"adverb","ipa":"/ˈɔːlsoʊ/","gloss":"também"},{"surface":"freezes","pos":"verb","ipa":"/ˈfriːzɪz/","gloss":"congela"},{"surface":"well","pos":"adverb","ipa":"/wɛl/","gloss":"bem"},{"surface":"Slice","pos":"verb","ipa":"/slaɪs/","gloss":"fatiar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"only","pos":"adverb","ipa":"/ˈoʊnli/","gloss":"só, apenas"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-09-05', 'lesson-paragraphs-b2-09', 5, 'paragraph', 'Another point is maintenance. When you rent, the owner usually pays for repairs, while owners must cover every problem themselves.', 'Outro ponto é a manutenção. Quando você aluga, o dono geralmente paga os reparos, enquanto os proprietários precisam arcar com cada problema.', '/əˈnʌðər pɔɪnt ɪz ˈmeɪntənəns wɛn juː rɛnt ðə ˈoʊnər ˈjuːʒuəli peɪz fɔːr rɪˈpɛrz waɪl ˈoʊnərz mʌst ˈkʌvər ˈɛvri ˈprɑːbləm ðəmˈsɛlvz/', '"While" contrasta duas situações. "Themselves" reforça quem paga.', '[]'::jsonb, '[{"surface":"Another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"point","pos":"noun","ipa":"/pɔɪnt/","gloss":"ponto, argumento"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"maintenance","pos":"noun","ipa":"/ˈmeɪntənəns/","gloss":"manutenção"},{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"rent","pos":"verb","ipa":"/rɛnt/","gloss":"alugar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"owner","pos":"noun","ipa":"/ˈoʊnər/","gloss":"dono"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"pays","pos":"verb","ipa":"/peɪz/","gloss":"paga"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"repairs","pos":"noun","ipa":"/rɪˈpɛrz/","gloss":"reparos"},{"surface":"while","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"owners","pos":"noun","ipa":"/ˈoʊnərz/","gloss":"donos, proprietários"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"cover","pos":"noun","ipa":"/ˈkʌvər/","gloss":"entrada (cover charge)"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"},{"surface":"themselves","pos":"pronoun","ipa":"/ðəmˈsɛlvz/","gloss":"eles mesmos"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-09-06', 'lesson-paragraphs-b2-09', 6, 'paragraph', 'Interest rates also matter. When they are high, a loan can cost much more than it seems at the beginning.', 'As taxas de juros também importam. Quando estão altas, um financiamento pode custar bem mais do que parece no começo.', '/ˈɪntrəst reɪts ˈɔːlsoʊ ˈmætər wɛn ðeɪ ɑːr haɪ ə loʊn kæn kɔːst mʌtʃ mɔːr ðæn ɪt siːmz æt ðə bɪˈɡɪnɪŋ/', '"When they are high" = condição geral. "Much more than" = comparativo.', '[]'::jsonb, '[{"surface":"Interest","pos":"noun","ipa":"/ˈɪntrəst/","gloss":"juros, interesse"},{"surface":"rates","pos":"noun","ipa":"/reɪts/","gloss":"preços, taxas"},{"surface":"also","pos":"adverb","ipa":"/ˈɔːlsoʊ/","gloss":"também"},{"surface":"matter","pos":"noun","ipa":"/ˈmætər/","gloss":"questão, assunto"},{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"high","pos":"adjective","ipa":"/haɪ/","gloss":"alto"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"loan","pos":"noun","ipa":"/loʊn/","gloss":"financiamento, empréstimo"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"cost","pos":"verb","ipa":"/kɔːst/","gloss":"custar"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"seems","pos":"verb","ipa":"/siːmz/","gloss":"parece"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"beginning","pos":"noun","ipa":"/bɪˈɡɪnɪŋ/","gloss":"começo"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-09-07', 'lesson-paragraphs-b2-09', 7, 'paragraph', 'There is an emotional side as well. Many people feel proud of owning a home, but others prefer the freedom of moving whenever they want.', 'Há também um lado emocional. Muita gente sente orgulho de ter uma casa, mas outros preferem a liberdade de se mudar quando quiserem.', '/ðɛr ɪz ən ɪˈmoʊʃənəl saɪd æz wɛl ˈmɛni ˈpiːpəl fiːl praʊd ʌv ˈoʊnɪŋ ə hoʊm bʌt ˈʌðərz prɪˈfɜːr ðə ˈfriːdəm ʌv ˈmuːvɪŋ wɛnˈɛvər ðeɪ wɑːnt/', '"Proud of" + -ing. "Whenever" = sempre que.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"emotional","pos":"adjective","ipa":"/ɪˈmoʊʃənəl/","gloss":"emocional"},{"surface":"side","pos":"noun","ipa":"/saɪd/","gloss":"lado"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"well","pos":"adverb","ipa":"/wɛl/","gloss":"bem"},{"surface":"Many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"proud","pos":"adjective","ipa":"/praʊd/","gloss":"orgulhoso"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"owning","pos":"verb","ipa":"/ˈoʊnɪŋ/","gloss":"possuir, ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"others","pos":"pronoun","ipa":"/ˈʌðərz/","gloss":"outros"},{"surface":"prefer","pos":"verb","ipa":"/prɪˈfɜːr/","gloss":"preferir"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"freedom","pos":"noun","ipa":"/ˈfriːdəm/","gloss":"liberdade"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"moving","pos":"verb","ipa":"/ˈmuːvɪŋ/","gloss":"mudar-se"},{"surface":"whenever","pos":"conjunction","ipa":"/wɛnˈɛvər/","gloss":"quando quer que"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-09-08', 'lesson-paragraphs-b2-09', 8, 'paragraph', 'Whichever option you choose, make a budget first. Knowing your numbers will protect you from decisions you may regret later.', 'Qualquer que seja a opção, faça um orçamento primeiro. Conhecer seus números vai protegê-lo de decisões de que pode se arrepender depois.', '/wɪˈtʃɛvər ˈɑːpʃən juː tʃuːz meɪk ə ˈbʌdʒɪt fɜːrst ˈnoʊɪŋ jʊr ˈnʌmbərz wɪl prəˈtɛkt juː frʌm dɪˈsɪʒənz juː meɪ rɪˈɡrɛt ˈleɪtər/', '"Whichever" = qualquer que seja. Sujeito com -ing: "Knowing your numbers".', '[]'::jsonb, '[{"surface":"Whichever","pos":"determiner","ipa":"/wɪˈtʃɛvər/","gloss":"qualquer que seja"},{"surface":"option","pos":"noun","ipa":"/ˈɑːpʃən/","gloss":"opção"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"choose","pos":"verb","ipa":"/tʃuːz/","gloss":"escolher"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"budget","pos":"noun","ipa":"/ˈbʌdʒɪt/","gloss":"orçamento"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"Knowing","pos":"verb","ipa":"/ˈnoʊɪŋ/","gloss":"saber, conhecer"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"numbers","pos":"noun","ipa":"/ˈnʌmbərz/","gloss":"números"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"protect","pos":"verb","ipa":"/prəˈtɛkt/","gloss":"proteger"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"decisions","pos":"noun","ipa":"/dɪˈsɪʒənz/","gloss":"decisões"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"regret","pos":"verb","ipa":"/rɪˈɡrɛt/","gloss":"lamentar"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-10-05', 'lesson-paragraphs-b2-10', 5, 'paragraph', 'My sister has promised to help me with the move. She will drive the truck, and I will organize the boxes.', 'Minha irmã prometeu me ajudar na mudança. Ela vai dirigir o caminhão, e eu vou organizar as caixas.', '/maɪ ˈsɪstər hæz ˈprɑːmɪst tuː hɛlp miː wɪð ðə muːv ʃiː wɪl draɪv ðə trʌk ænd aɪ wɪl ˈɔːrɡənaɪz ðə ˈbɑːksɪz/', 'Present perfect para uma promessa feita. "Will" para decisões combinadas.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"sister","pos":"noun","ipa":"/ˈsɪstər/","gloss":"irmã"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"promised","pos":"verb","ipa":"/ˈprɑːmɪst/","gloss":"prometeu"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"move","pos":"verb","ipa":"/muːv/","gloss":"mover, passar"},{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"drive","pos":"verb","ipa":"/draɪv/","gloss":"dirigir"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"truck","pos":"noun","ipa":"/trʌk/","gloss":"caminhão"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"organize","pos":"verb","ipa":"/ˈɔːrɡənaɪz/","gloss":"organizar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"boxes","pos":"noun","ipa":"/ˈbɑːksɪz/","gloss":"caixas"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-10-06', 'lesson-paragraphs-b2-10', 6, 'paragraph', 'I also plan to join a language class in the new city. Meeting people is the fastest way to feel at home.', 'Também pretendo entrar numa aula de idiomas na cidade nova. Conhecer pessoas é o jeito mais rápido de se sentir em casa.', '/aɪ ˈɔːlsoʊ plæn tuː dʒɔɪn ə ˈlæŋɡwɪdʒ klæs ɪn ðə nuː ˈsɪti ˈmiːtɪŋ ˈpiːpəl ɪz ðə ˈfæstɪst weɪ tuː fiːl æt hoʊm/', '"Plan to" + verbo. Sujeito com -ing e superlativo "the fastest".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"also","pos":"adverb","ipa":"/ˈɔːlsoʊ/","gloss":"também"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"join","pos":"verb","ipa":"/dʒɔɪn/","gloss":"entrar, participar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"language","pos":"noun","ipa":"/ˈlæŋɡwɪdʒ/","gloss":"língua, idioma"},{"surface":"class","pos":"noun","ipa":"/klæs/","gloss":"aula, turma"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"},{"surface":"Meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"fastest","pos":"adjective","ipa":"/ˈfæstɪst/","gloss":"o mais rápido"},{"surface":"way","pos":"noun","ipa":"/weɪ/","gloss":"caminho; jeito"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-10-07', 'lesson-paragraphs-b2-10', 7, 'paragraph', 'In five years, I would like to be working in a job I truly enjoy. I hope to be living near the sea, too.', 'Daqui a cinco anos, gostaria de estar trabalhando num emprego de que realmente gosto. Espero estar morando perto do mar também.', '/ɪn faɪv jɪrz aɪ wʊd laɪk tuː biː ˈwɜːrkɪŋ ɪn ə dʒɑːb aɪ ˈtruːli ɪnˈdʒɔɪ aɪ hoʊp tuː biː ˈlɪvɪŋ nɪr ðə siː tuː/', 'Future continuous com infinitivo ("to be working"). "In five years" = daqui a cinco anos.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"truly","pos":"adverb","ipa":"/ˈtruːli/","gloss":"realmente"},{"surface":"enjoy","pos":"verb","ipa":"/ɪnˈdʒɔɪ/","gloss":"aproveitar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"hope","pos":"verb","ipa":"/hoʊp/","gloss":"esperar (ter esperança)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"living","pos":"adjective","ipa":"/ˈlɪvɪŋ/","gloss":"de estar"},{"surface":"near","pos":"preposition","ipa":"/nɪr/","gloss":"perto de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"sea","pos":"noun","ipa":"/siː/","gloss":"mar"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-10-08', 'lesson-paragraphs-b2-10', 8, 'paragraph', 'Of course, nothing is certain. But I would rather try and fail than wonder what could have happened.', 'Claro, nada é certo. Mas prefiro tentar e falhar a ficar me perguntando o que poderia ter acontecido.', '/ʌv kɔːrs ˈnʌθɪŋ ɪz ˈsɜːrtən bʌt aɪ wʊd ˈræðər traɪ ænd feɪl ðæn ˈwʌndər wʌt kʊd hæv ˈhæpənd/', '"Would rather ... than" compara preferências. "Could have happened" = possibilidade no passado.', '[]'::jsonb, '[{"surface":"Of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"course","pos":"noun","ipa":"/kɔːrs/","gloss":"curso (of course = claro)"},{"surface":"nothing","pos":"pronoun","ipa":"/ˈnʌθɪŋ/","gloss":"nada"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"certain","pos":"adjective","ipa":"/ˈsɜːrtən/","gloss":"certo, seguro"},{"surface":"But","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"rather","pos":"adverb","ipa":"/ˈræðər/","gloss":"de preferência"},{"surface":"try","pos":"verb","ipa":"/traɪ/","gloss":"experimentar, tentar"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"fail","pos":"verb","ipa":"/feɪl/","gloss":"reprovar, falhar"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"wonder","pos":"verb","ipa":"/ˈwʌndər/","gloss":"perguntar-se"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"happened","pos":"verb","ipa":"/ˈhæpənd/","gloss":"aconteceu"}]'::jsonb, NULL, NULL)
